export function wishDirectionForNakshatra(star27Index) {
  const self = wishSelfDirections[star27Index];
  const blessing = wishBlessingDirections[star27Index];
  return {
    starIndex: star27Index,
    self,
    selfText: `${self} မျက်နှာမူပါ။`,
    selfAngle: wishDirectionAngles[self],
    blessing,
    blessingText: `${blessing} မျက်နှာမူပါ။`,
    blessingAngle: wishDirectionAngles[blessing],
  };
}
